CREATE TABLE cleaned_measurements AS
SELECT * FROM measurements
WHERE cognitive_score >= (SELECT AVG(cognitive_score) FROM measurements) - 3 *
(
    SELECT (SELECT AVG(cognitive_score * cognitive_score) FROM measurements) - (SELECT AVG(cognitive_score) FROM measurements) * (SELECT AVG(cognitive_score) FROM measurements)
);
AND cognitive_score <= (SELECT AVG(cognitive_score) FROM measurements) + 3 *
(
    SELECT (SELECT AVG(cognitive_score * cognitive_score) FROM measurements) - (SELECT AVG(cognitive_score) FROM measurements) * (SELECT AVG(cognitive_score) FROM measurements)
);
